#include <stdarg.h>
#include "../common/retro-games/puzzles/vendor/range.c"
void fatal(const char *format,...){va_list a;va_start(a,format);vfprintf(stderr,format,a);va_end(a);fputc('\n',stderr);exit(2);}
void frontend_default_colour(frontend *f,float *out){(void)f;out[0]=out[1]=out[2]=0.9F;}
static game_params *params;
static game_state *from_id(const char *id){char *copy=dupstr(id),*p=strchr(copy,':');if(!p)fatal("Missing ID");*p++=0;params=default_params();decode_params(params,copy);const char *e=validate_params(params,true);if(!e)e=validate_desc(params,p);if(e)fatal("Original validation: %s",e);game_state *s=new_game(NULL,params,p);sfree(copy);return s;}
static game_state *step(game_state *s,const char *m){game_state *n=execute_move(s,m);if(!n)fatal("Original rejection: %s",m);free_game(s);return n;}
static unsigned colour565(float *p,int c){unsigned r=(unsigned)(p[3*c]*255+.5F),g=(unsigned)(p[3*c+1]*255+.5F),b=(unsigned)(p[3*c+2]*255+.5F);return ((r>>3)<<11)|((g>>2)<<5)|(b>>3);}
static void output(game_state *s){int n;float *p=game_colours(NULL,&n);bool *errors=snewn(s->params.w*s->params.h,bool);memset(errors,0,s->params.w*s->params.h*sizeof(bool));find_errors(s,errors);printf("{\"w\":%d,\"h\":%d,\"status\":%d,\"cheated\":%d,\"white_dot\":%u,\"cells\":[",s->params.w,s->params.h,game_status(s),s->has_cheated,colour565(p,COL_USER));for(int i=0;i<s->params.w*s->params.h;i++){int v=s->grid[i],c=v==BLACK?(errors[i]?COL_ERROR:COL_BLACK):COL_BACKGROUND;printf("%s[%d,%d,%u]",i?",":"",v,errors[i],colour565(p,c));}puts("]}");sfree(errors);sfree(p);}
static void self_test(void){game_state *s=from_id("3x3:d5d");game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,24);char *m=interpret_move(s,ui,ds,24,24,LEFT_BUTTON);assert(!strcmp(m,"B,0,0"));sfree(m);m=interpret_move(s,ui,ds,24,24,RIGHT_BUTTON);assert(!strcmp(m,"W,0,0"));sfree(m);assert(interpret_move(s,ui,ds,48,48,LEFT_BUTTON)==NULL);assert(interpret_move(s,ui,ds,-24,24,LEFT_BUTTON)==NULL);game_free_drawstate(NULL,ds);free_ui(ui);assert(execute_move(s,"B,3,0")==NULL&&execute_move(s,"invalid")==NULL);
 s=step(s,"B,0,1");assert(find_errors(s,NULL)&&!game_status(s));free_game(s);free_params(params);
 s=from_id("3x3:i");s=step(s,"B,0,0B,0,1");assert(find_errors(s,NULL)&&!game_status(s));free_game(s);free_params(params);
 s=from_id("3x3:i");s=step(s,"B,0,1B,1,0B,1,2B,2,1");assert(find_errors(s,NULL)&&!game_status(s));free_game(s);free_params(params);
 s=from_id("3x3:d5d");s=step(s,"W,0,0");assert(!find_errors(s,NULL)&&game_status(s)==1&&!s->has_cheated);free_game(s);free_params(params);
 puts("PASS: original Left black/Right white cycles, fixed clue and out-of-board rejection, invalid bounds/syntax, visibility count error, adjacent-black error, disconnected-white error, uncheated victory");}
int main(int argc,char **argv){if(argc==2&&!strcmp(argv[1],"--self-test")){self_test();return 0;}if(argc>=7&&!strcmp(argv[1],"--input")){game_state *s=from_id(argv[2]);for(int i=7;i<argc;i++)s=step(s,argv[i]);game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,atoi(argv[3]));char *m=interpret_move(s,ui,ds,atoi(argv[4]),atoi(argv[5]),!strcmp(argv[6],"R")?RIGHT_BUTTON:LEFT_BUTTON);if(!m||m==MOVE_UI_UPDATE||m==MOVE_NO_EFFECT||m==MOVE_UNUSED)fatal("Original input has no move");puts(m);sfree(m);game_free_drawstate(NULL,ds);free_ui(ui);free_game(s);free_params(params);return 0;}if(argc<2)fatal("Usage: native-oracle ID [moves]");game_state *s=from_id(argv[1]);for(int i=2;i<argc;i++)s=step(s,argv[i]);output(s);free_game(s);free_params(params);return 0;}
